import{c as s,Q as n,j as e,m as t}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"PlatformAscendCManager","description":"","frontmatter":{},"headers":[{"level":1,"title":"PlatformAscendCManager","slug":"platformascendcmanager"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/平台信息获取/PlatformAscendCManager.md","filePath":"api/Utils-API/平台信息获取/PlatformAscendCManager.md"}'),l={name:"api/Utils-API/平台信息获取/PlatformAscendCManager.md"};function i(p,a,c,o,r,d){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="platformascendcmanager" tabindex="-1">PlatformAscendCManager <a class="header-anchor" href="#platformascendcmanager" aria-label="Permalink to &quot;PlatformAscendCManager&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>基于Kernel Launch算子工程，通过Kernel直调（Kernel Launch）方式调用算子的场景下，可能需要获取硬件平台相关信息，比如获取硬件平台的核数。PlatformAscendCManager类提供获取平台信息的功能：通过该类的GetInstance方法可以获取一个PlatformAscendC类的指针，再通过该指针获取硬件平台相关信息，支持获取的信息可参考<a href="./PlatformAscendC/PlatformAscendC.html">PlatformAscendC</a>。</p><div class="caution custom-block github-alert"><p class="custom-block-title">注意</p><p></p><ul><li>使用该功能需要包含&quot;tiling/platform/platform_ascendc.h&quot;头文件，并在编译脚本中链接tiling_api、platform动态库。</li><li>包含头文件的样例如下：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;tiling/platform/platform_ascendc.h&quot;</span></span></code></pre></div></li><li>链接动态库的样例如下:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_executable(main main.cpp)</span></span>
<span class="line"><span>target_link_libraries(main PRIVATE</span></span>
<span class="line"><span>  kernels</span></span>
<span class="line"><span>  tiling_api</span></span>
<span class="line"><span>  platform</span></span>
<span class="line"><span>)</span></span></code></pre></div></li><li>当前该类仅支持如下型号：</li><li>Atlas 推理系列产品</li><li>Atlas 训练系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class PlatformAscendCManager {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    static PlatformAscendC* GetInstance();</span></span>
<span class="line"><span>    // 在仅有CPU环境、无对应的NPU硬件环境时，需要传入customSocVersion来指定对应的AI处理器型号。注意：因为GetInstance实现属于单例模式，仅在第一次调用时传入的customSocVersion生效。</span></span>
<span class="line"><span>    static PlatformAscendC* GetInstance(const char *customSocVersion);</span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>customSocVersion</td><td>输入</td><td>AI处理器型号。 针对如下产品：在安装AI处理器的服务器执行npu-smi info命令进行查询，获取Name信息。实际配置值为AscendName，例如Name取值为xxxyy，实际配置值为Ascendxxxyy。 Atlas A2 训练系列产品/Atlas A2 推理系列产品 Atlas 200I/500 A2 推理产品 Atlas 推理系列产品 Atlas 训练系列产品 针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，在安装AI处理器的服务器执行npu-smi info -t board -i id -c chip_id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。其中：id：设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。chip_id：芯片id，通过npu-smi info -m命令查出的Chip ID即为芯片id。 针对Ascend 950PR/Ascend 950DT，在安装AI处理器的服务器执行npu-smi info -t board -i id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。 其中，id为设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GetInfoFun() {</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    auto coreNum = platform_ascendc::PlatformAscendCManager::GetInstance()-&gt;GetCoreNum();</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,14)])])}const u=s(l,[["render",i]]);export{m as __pageData,u as default};
